import json,re,statistics
from decimal import Decimal,InvalidOperation
from pathlib import Path
from collections import Counter
pat=re.compile(r'#### (\-?[0-9\.\,]+)')
def correct(r):
 answers=pat.findall(r['output'])
 try: return bool(answers) and Decimal(answers[-1].replace(',',''))==Decimal(r['gts'].replace(',',''))
 except InvalidOperation: return False
for name in ['50','100']:
 rows=[json.loads(s) for s in Path(f'results/run100/val_generations/{name}.jsonl').open()]
 print(name,Counter((len(pat.findall(r['output']))>0, correct(r)) for r in rows))
a=[json.loads(s) for s in Path('results/run100/val_generations/50.jsonl').open()]
b=[json.loads(s) for s in Path('results/run100/val_generations/100.jsonl').open()]
print('50->100 transitions',Counter((correct(r),correct(s)) for r,s in zip(a,b)))
for s in [1,50,100]:
 rows=[json.loads(l) for l in Path(f'results/run100/rollouts/{s}.jsonl').open()]
 by_prompt={}
 for r in rows: by_prompt.setdefault(r['input'],[]).append(r)
 group_counts=Counter(sum(correct(r) for r in grp) for grp in by_prompt.values())
 print('STEP',s,'prompts',len(by_prompt),'sizes',Counter(len(g) for g in by_prompt.values()),'correct per group',group_counts)
PY",workdir:"/workspace",max_output_tokens:1400})
